function calculateEngagement() {
  const followers = parseFloat(document.getElementById('followers').value);
  const likes = parseFloat(document.getElementById('likes').value);
  const comments = parseFloat(document.getElementById('comments').value);

  if (isNaN(followers) || isNaN(likes) || isNaN(comments) || followers <= 0) {
    showError('Please enter valid positive numbers');
    return;
  }

  const rate = ((likes + comments) / followers) * 100;
  const rounded = rate.toFixed(1);

  let quality = 'okay';
  if (rate >= 5) quality = 'excellent';
  else if (rate >= 2) quality = 'good';

  displayResult(rounded, quality);
}

const links = [
  { title: 'YouTube', url: 'https://youtube.com/@creator' },
  { title: 'Instagram', url: 'https://instagram.com/creator' },
  { title: 'Website', url: 'https://creator.com' }
];

function renderLinks() {
  const container = document.getElementById('links');
  let totalClicks = parseInt(localStorage.getItem('totalClicks') || '0');

  links.forEach(link => {
    const button = document.createElement('a');
    button.className = 'link-button';
    button.textContent = link.title;
    button.href = link.url;
    button.target = '_blank';
    button.onclick = () => {
      totalClicks++;
      localStorage.setItem('totalClicks', totalClicks);
    };
    container.appendChild(button);
  });

  document.getElementById('clicks').textContent = `Total clicks: ${totalClicks}`;
}
